sys_security_acl.script:
answer = false;

// 1. Full view access for Admins, Placement Officers, and HRs
if (gs.hasRole('x_snc_college_pl_0.placement_officer') || 
    gs.hasRole('x_snc_college_pl_0.placement_admin') || 
    gs.hasRole('x_snc_college_pl_0.interviewer')) {

    answer = true;

// 2. Allow students to view when creating a new record OR when accessing their own application
} else if (current.isNewRecord() || (current.student && current.student.user == gs.getUserID())) {
    answer = true;
}
